Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long v;
vector<long long> pattern(17);

int find_min(int index, long long value) {
    value = abs(value);
    if (index == 0) {
        return static_cast<int>(value);
    }
    int q = static_cast<int>(value / pattern[index]);
    int q_plus = q + 1;
    int cost_q = q * (index + 1) + find_min(index - 1, value - q * pattern[index]);
    int cost_qp = q_plus * (index + 1) + find_min(index - 1, value - q_plus * pattern[index]);
    return min(cost_q, cost_qp);
}

int main() {
    cin >> v;
    pattern[0] = 1;
    for (int i = 1; i < 17; ++i) {
        pattern[i] = pattern[i - 1] * 10 + 1;
    }
    cout << find_min(16, v) << "\n";
    return 0;
}
